window.MAPS = (window.MAPS||[]).concat([
{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"A2", icon:"🔄", t:"Present Simple vs Present Continuous", es:"Presente simple vs presente continuo", d:"Rutinas y hechos frente a acciones que ocurren ahora o temporalmente.",
 boxes:[
  {e:"📅", h:"Present Simple: form", es:"Forma", i:[["I/you/we/they + verb: I work in Leeds.","Yo/tú/nosotros/ellos + verbo: Trabajo en Leeds."],["he/she/it + verb + -s: She works in Leeds.","Él/ella + verbo + -s: Ella trabaja en Leeds."],["Questions: do/does + subject + verb: Does he live here?","Preguntas con do/does: ¿Vive él aquí?"]], ex:["My brother lives in Bristol.","Mi hermano vive en Bristol."]},
  {e:"🔁", h:"Present Simple: use", es:"Uso", i:[["Habits and routines: I catch the 7.45 train.","Hábitos y rutinas: Tomo el tren de las 7.45."],["Facts and general truths: Water boils at 100 degrees.","Hechos y verdades generales: El agua hierve a 100 grados."],["Timetables: The film starts at 20:30.","Horarios: La película empieza a las 20:30."]], ex:["The shops open at nine.","Las tiendas abren a las nueve."]},
  {e:"⏱️", h:"Present Continuous: form", es:"Forma", i:[["am/is/are + verb-ing: I'm waiting for the bus.","am/is/are + verbo-ing: Estoy esperando el autobús."],["Negative: They aren't working.","Negativa: No están trabajando."],["Question: Is it raining?","Pregunta: ¿Está lloviendo?"]], ex:["She's talking on her mobile.","Está hablando por el celular."]},
  {e:"📍", h:"Present Continuous: use", es:"Uso", i:[["Happening now: He's making a cup of tea.","Ocurre ahora: Está preparando una taza de té."],["Temporary situations: I'm staying with a friend this week.","Situaciones temporales: Esta semana me estoy quedando con un amigo."],["Changing trends: Prices are rising.","Tendencias cambiantes: Los precios están subiendo."]], ex:["I'm living in a flat in Camden at the moment.","Vivo en un apartamento en Camden por ahora."]},
  {e:"🔔", h:"Signal words", es:"Palabras clave", i:[["always, usually, every day, never: He usually walks to work.","siempre, normalmente, cada día, nunca: Normalmente camina al trabajo."],["now, at the moment, today, this week: We're revising this week.","ahora, en este momento, hoy, esta semana: Esta semana estamos repasando."]], ex:["I never drink coffee, but today I'm having one.","Nunca tomo café, pero hoy me estoy tomando uno."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I'm knowing the answer.","✓ I know the answer. — 'know' es un verbo de estado, no admite -ing."],["✗ She work in a bank.","✓ She works in a bank. — falta la -s de la tercera persona."],["✗ Does he works here?","✓ Does he work here? — tras does, verbo sin -s."]], ex:["Are you listening to me?","¿Me estás escuchando?"]}
 ], qs:[
  {q:"Look! It ____ (rain) and I ____ (not have) an umbrella.", a:"is raining / don't have — 'Look!' = ahora; 'have' (poseer) es estativo."},
  {q:"Choose: Tom (plays / is playing) football every Saturday.", a:"plays — hábito, presente simple."},
  {q:"Correct the mistake: She is liking her new flat.", a:"She likes her new flat. — 'like' es verbo de estado."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🧠", t:"Stative Verbs", es:"Verbos de estado", d:"Verbos que normalmente no se usan en forma continua y sus excepciones.",
 boxes:[
  {e:"💭", h:"Thinking verbs", es:"Verbos de pensamiento", i:[["know, understand, believe, remember: I don't understand this.","saber, entender, creer, recordar: No entiendo esto."],["think (opinion), doubt, forget: I think it's too expensive.","pensar (opinión), dudar, olvidar: Creo que es demasiado caro."]], ex:["I don't remember her name.","No recuerdo su nombre."]},
  {e:"❤️", h:"Feeling verbs", es:"Verbos de sentimiento", i:[["like, love, hate, prefer, want: I prefer tea to coffee.","gustar, amar, odiar, preferir, querer: Prefiero el té al café."],["need, wish, mind: Do you mind waiting?","necesitar, desear, importar: ¿Te importa esperar?"]], ex:["She loves living in Edinburgh.","Le encanta vivir en Edimburgo."]},
  {e:"🏠", h:"Possession & being", es:"Posesión y ser", i:[["have got, own, belong: This flat belongs to my aunt.","tener, poseer, pertenecer: Este apartamento pertenece a mi tía."],["be, seem, appear: He seems tired.","ser/estar, parecer: Parece cansado."]], ex:["I've got two sisters.","Tengo dos hermanas."]},
  {e:"👃", h:"Senses", es:"Sentidos", i:[["smell, taste, sound, look (state): This soup tastes lovely.","oler, saber, sonar, parecer: Esta sopa sabe deliciosa."],["Use can for ability: I can hear music.","Usa can para la capacidad: Oigo música."]], ex:["That sounds like a good idea.","Eso suena a buena idea."]},
  {e:"🔀", h:"Dynamic meanings", es:"Significados dinámicos", i:[["have = eat (action): We're having lunch.","have = comer (acción): Estamos almorzando."],["think = opinion / thinking = process: I'm thinking about my holiday.","think = opinión / thinking = proceso: Estoy pensando en mis vacaciones."],["be + -ing = behaving: You're being silly.","be + -ing = comportarse: Estás haciendo el tonto."]], ex:["She's having a bath at the moment.","Se está dando un baño ahora."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I am wanting a biscuit.","✓ I want a biscuit. — 'want' no se usa en continuo."],["✗ I am knowing him.","✓ I know him. — verbo de estado."],["✗ She is having two sisters.","✓ She has (got) two sisters. — 'have' = posesión, sin -ing."]], ex:["I don't believe you.","No te creo."]}
 ], qs:[
  {q:"Choose: I (am wanting / want) a cup of tea.", a:"want — verbo de estado, sin continuo."},
  {q:"Fill the gap: We ____ (have) lunch at the moment. Can I ring you back?", a:"are having — 'have' = comer es acción, admite continuo."},
  {q:"Correct the mistake: I'm not understanding this exercise.", a:"I don't understand this exercise. — 'understand' es estativo."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"A2", icon:"⌛", t:"Past Simple (Regular & Irregular)", es:"Pasado simple (regulares e irregulares)", d:"Cómo formar y usar el pasado simple para acciones terminadas.",
 boxes:[
  {e:"✍️", h:"Regular verbs", es:"Verbos regulares", i:[["verb + -ed: I walked to school.","verbo + -ed: Fui caminando al colegio."],["Spelling: study → studied, stop → stopped: She studied hard.","Ortografía: study → studied, stop → stopped: Estudió mucho."]], ex:["We visited Bath last summer.","Visitamos Bath el verano pasado."]},
  {e:"🔤", h:"Irregular verbs", es:"Verbos irregulares", i:[["go → went, see → saw, buy → bought: He bought a flat.","ir, ver, comprar: Compró un apartamento."],["get → got, take → took, come → came: They came by coach.","conseguir, tomar, venir: Vinieron en autobús."]], ex:["I saw her at the station.","La vi en la estación."]},
  {e:"❌", h:"Negatives", es:"Negativas", i:[["didn't + base verb: I didn't go out.","didn't + verbo base: No salí."],["Never 'didn't went': She didn't see him.","Nunca 'didn't went': Ella no lo vio."]], ex:["They didn't arrive on time.","No llegaron a tiempo."]},
  {e:"❓", h:"Questions", es:"Preguntas", i:[["Did + subject + base verb? Did you enjoy the match?","Did + sujeto + verbo base: ¿Disfrutaste del partido?"],["Wh- + did + subject + verb: Where did she park?","Wh- + did + sujeto + verbo: ¿Dónde estacionó ella?"]], ex:["What time did the train leave?","¿A qué hora salió el tren?"]},
  {e:"📆", h:"Time expressions", es:"Expresiones de tiempo", i:[["yesterday, last week, in 2019: We moved in 2019.","ayer, la semana pasada, en 2019: Nos mudamos en 2019."],["two days ago, at the weekend: I rang her two days ago.","hace dos días, el fin de semana: La llamé hace dos días."]], ex:["I met him a fortnight ago.","Lo conocí hace dos semanas."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I didn't went to work.","✓ I didn't go to work. — tras didn't, verbo base."],["✗ Did you saw him?","✓ Did you see him? — tras did, verbo base."],["✗ I have seen him yesterday.","✓ I saw him yesterday. — con 'yesterday', pasado simple."]], ex:["She wanted a cup of tea.","Quería una taza de té."]}
 ], qs:[
  {q:"Yesterday I ____ (not/go) to work because I ____ (feel) ill.", a:"didn't go / felt — negativa con didn't + base; feel es irregular."},
  {q:"Choose: Where (did you buy / you bought / did you bought) that jacket?", a:"did you buy — pregunta con did + verbo base."},
  {q:"Correct the mistake: We goed to Brighton last weekend.", a:"We went to Brighton last weekend. — 'go' es irregular: went."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🎬", t:"Past Continuous", es:"Pasado continuo", d:"Acciones en progreso en un momento del pasado y escenas de fondo.",
 boxes:[
  {e:"🧩", h:"Form", es:"Forma", i:[["was/were + verb-ing: I was reading.","was/were + verbo-ing: Estaba leyendo."],["Negative: They weren't listening.","Negativa: No estaban escuchando."]], ex:["He was cooking dinner.","Estaba preparando la cena."]},
  {e:"❓", h:"Questions", es:"Preguntas", i:[["Was/Were + subject + -ing? Were you sleeping?","Was/Were + sujeto + -ing: ¿Estabas durmiendo?"],["Wh- question: What were you doing?","Pregunta con wh-: ¿Qué estabas haciendo?"]], ex:["Where were they going?","¿Adónde iban?"]},
  {e:"🕗", h:"Action at a moment", es:"Acción en un momento", i:[["At 8 o'clock I was having breakfast.","A las ocho estaba desayunando."],["This time yesterday, we were queuing.","A esta hora ayer estábamos haciendo cola."]], ex:["At half past nine she was driving to Leeds.","A las nueve y media conducía hacia Leeds."]},
  {e:"🖼️", h:"Scene setting", es:"Ambientación", i:[["Background in stories: The sun was shining.","Fondo en los relatos: Brillaba el sol."],["Several scenes at once: Children were playing; a dog was barking.","Varias escenas a la vez: Niños jugando; un perro ladraba."]], ex:["It was raining and people were hurrying home.","Llovía y la gente volvía deprisa a casa."]},
  {e:"👯", h:"Parallel actions", es:"Acciones paralelas", i:[["while + past continuous: While I was cooking, he was washing up.","while + pasado continuo: Mientras yo cocinaba, él fregaba."],["as = while: As I was walking, I saw Tom.","as = while: Mientras caminaba, vi a Tom."]], ex:["She was reading while the kids were playing.","Ella leía mientras los niños jugaban."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I was knowing the answer.","✓ I knew the answer. — los verbos de estado no van en continuo."],["✗ I was watch TV.","✓ I was watching TV. — was + verbo-ing."],["✗ What you were doing?","✓ What were you doing? — el auxiliar va antes del sujeto."]], ex:["I didn't know what to say.","No sabía qué decir."]}
 ], qs:[
  {q:"At 10 p.m. last night, I ____ (watch) the news.", a:"was watching — acción en progreso en un momento concreto."},
  {q:"Choose: What (were you doing / did you doing / you were doing) at eight?", a:"were you doing — pregunta en pasado continuo."},
  {q:"Correct the mistake: They was playing in the garden.", a:"They were playing in the garden. — 'they' lleva were."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"⚡", t:"Past Simple vs Past Continuous", es:"Pasado simple vs pasado continuo", d:"Acción interrumpida frente a acción interrumpidora en el pasado.",
 boxes:[
  {e:"✅", h:"Past Simple", es:"Acción terminada", i:[["Completed, short action: He phoned me.","Acción corta y terminada: Me llamó."],["Sequence of events: I woke up, got dressed and left.","Secuencia de hechos: Me desperté, me vestí y salí."]], ex:["She opened the door and smiled.","Abrió la puerta y sonrió."]},
  {e:"⏳", h:"Past Continuous", es:"Acción en progreso", i:[["Longer background action: I was walking home.","Acción larga de fondo: Iba caminando a casa."],["Unfinished at that time: It was snowing.","Sin terminar en ese momento: Estaba nevando."]], ex:["We were waiting for the bus.","Estábamos esperando el autobús."]},
  {e:"💥", h:"Interrupted action", es:"Acción interrumpida", i:[["Long action + short action: I was having a shower when the phone rang.","Acción larga + corta: Me estaba duchando cuando sonó el teléfono."],["The short action is past simple: The lights went out while we were eating.","La acción corta va en pasado simple: Se apagó la luz mientras comíamos."]], ex:["He was crossing the road when a bike hit him.","Cruzaba la calle cuando lo atropelló una bicicleta."]},
  {e:"🔗", h:"when / while / as", es:"Conectores", i:[["when + past simple: When the bell rang, I left.","when + pasado simple: Cuando sonó el timbre, me fui."],["while / as + past continuous: While I was working, he arrived.","while / as + pasado continuo: Mientras trabajaba, él llegó."]], ex:["As she was leaving, it started to rain.","Mientras salía, empezó a llover."]},
  {e:"🎞️", h:"Story structure", es:"Estructura de relato", i:[["Background: past continuous: It was getting dark.","Fondo: pasado continuo: Estaba oscureciendo."],["Events: past simple: Suddenly, a light appeared.","Hechos: pasado simple: De repente apareció una luz."]], ex:["It was raining when I got to the station.","Llovía cuando llegué a la estación."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ When I was arriving, she left.","✓ When I arrived, she left. — acción corta y puntual: pasado simple."],["✗ I was having a shower when the phone was ringing.","✓ ...when the phone rang. — la interrupción va en pasado simple."],["✗ He was ringing me three times yesterday.","✓ He rang me three times yesterday. — acción repetida y terminada: pasado simple."]], ex:["I was writing an email when you rang.","Escribía un correo cuando llamaste."]}
 ], qs:[
  {q:"She ____ (cross) the road when a cyclist ____ (hit) her.", a:"was crossing / hit — acción larga interrumpida por una corta."},
  {q:"Choose: I (was watching / watched) TV when the lights went out.", a:"was watching — acción en progreso interrumpida."},
  {q:"Correct the mistake: While we had dinner, the doorbell was ringing.", a:"While we were having dinner, the doorbell rang. — fondo en continuo, interrupción en simple."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"✔️", t:"Present Perfect Simple", es:"Pretérito perfecto simple", d:"Experiencias, resultados presentes y acciones sin tiempo concreto.",
 boxes:[
  {e:"🧱", h:"Form", es:"Forma", i:[["have/has + past participle: I've finished.","have/has + participio: He terminado."],["Negative: She hasn't called.","Negativa: No ha llamado."],["Question: Have you eaten?","Pregunta: ¿Has comido?"]], ex:["They have moved to Manchester.","Se han mudado a Mánchester."]},
  {e:"🌍", h:"Life experience", es:"Experiencias", i:[["ever / never: Have you ever been to Wales?","ever / never: ¿Has estado alguna vez en Gales?"],["It's the first time...: It's the first time I've seen snow.","Es la primera vez...: Es la primera vez que veo nieve."]], ex:["I've never tried haggis.","Nunca he probado el haggis."]},
  {e:"🔑", h:"Present result", es:"Resultado actual", i:[["Past action, present relevance: I've lost my keys. (I can't get in)","Acción pasada con relevancia actual: He perdido las llaves. (No puedo entrar)"],["Visible result now: She's broken her arm.","Resultado visible ahora: Se ha roto el brazo."]], ex:["The bus has left, so we'll walk.","El autobús se ha ido, así que iremos a pie."]},
  {e:"🆕", h:"Just, already, yet", es:"Just, already, yet", i:[["just = a moment ago: I've just seen him.","just = hace un momento: Acabo de verlo."],["already = earlier than expected: She's already left.","already = antes de lo esperado: Ya se ha ido."],["yet = questions/negatives: Haven't you finished yet?","yet = preguntas/negativas: ¿Aún no has terminado?"]], ex:["I haven't done my homework yet.","Todavía no he hecho los deberes."]},
  {e:"📏", h:"For and since", es:"For y since", i:[["for + period: for three years","for + periodo: durante tres años"],["since + starting point: since 2020 / since Monday","since + punto de inicio: desde 2020 / desde el lunes"]], ex:["I've lived here for ten years.","Vivo aquí desde hace diez años."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I live here since 2018.","✓ I've lived here since 2018. — acción que continúa: presente perfecto."],["✗ I have seen him yesterday.","✓ I saw him yesterday. — tiempo terminado: pasado simple."],["✗ I have went to Wales.","✓ I have been to Wales. — 'went' es pasado, no participio; ir y volver: been (gone = sigue allí)."]], ex:["Have you got a pen I could borrow?","¿Tienes un bolígrafo que me puedas prestar?"]}
 ], qs:[
  {q:"I ____ (live) in London since 2018.", a:"have lived — 'since' + punto de inicio = presente perfecto."},
  {q:"Choose: She (has just left / just left yesterday). Pick the correct one.", a:"has just left — 'just' con presente perfecto; 'yesterday' exige pasado simple."},
  {q:"Correct the mistake: I am here since nine o'clock.", a:"I've been here since nine o'clock. — acción que empezó antes y continúa."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🏃", t:"Present Perfect Continuous", es:"Pretérito perfecto continuo", d:"Acciones que empezaron en el pasado y continúan o acaban de terminar.",
 boxes:[
  {e:"🧱", h:"Form", es:"Forma", i:[["have/has + been + verb-ing: I've been waiting.","have/has + been + verbo-ing: He estado esperando."],["Negative: She hasn't been sleeping well.","Negativa: No ha estado durmiendo bien."]], ex:["They've been working all day.","Han estado trabajando todo el día."]},
  {e:"⏳", h:"Ongoing action", es:"Acción en curso", i:[["Started in the past, still going: I've been learning English for two years.","Empezó en el pasado y continúa: Llevo dos años aprendiendo inglés."],["Often with for/since: I've been waiting since nine.","Suele ir con for/since: Llevo esperando desde las nueve."]], ex:["It's been raining since breakfast.","Lleva lloviendo desde el desayuno."]},
  {e:"👀", h:"Recent evidence", es:"Evidencia reciente", i:[["Visible result of recent activity: You're red — have you been running?","Resultado visible de actividad reciente: Estás rojo, ¿has estado corriendo?"],["Explains a present state: He's out of breath; he's been running.","Explica un estado actual: Está sin aliento; ha estado corriendo."]], ex:["Her hands are dirty; she's been gardening.","Tiene las manos sucias; ha estado trabajando en el jardín."]},
  {e:"❓", h:"How long?", es:"¿Cuánto tiempo?", i:[["How long have you been waiting?","¿Cuánto tiempo llevas esperando?"],["Answer with for/since: For six months. / Since January.","Respuesta con for/since: Seis meses. / Desde enero."]], ex:["How long have you been learning the guitar?","¿Cuánto tiempo llevas aprendiendo guitarra?"]},
  {e:"🔔", h:"Signal words", es:"Palabras clave", i:[["for, since, all day, lately, recently: I've been feeling tired lately.","for, since, todo el día, últimamente: Últimamente me siento cansado."],["She's been working a lot recently.","Ha estado trabajando mucho recientemente."]], ex:["We've been queuing for an hour.","Llevamos una hora haciendo cola."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I'm waiting here for an hour.","✓ I've been waiting here for an hour. — duración hasta ahora: perfecto continuo."],["✗ I've been knowing her for years.","✓ I've known her for years. — verbo de estado: perfecto simple."],["✗ I have been wait since nine.","✓ I have been waiting since nine. — been + verbo-ing."]], ex:["I've had this mobile for ages.","Tengo este celular desde hace siglos."]}
 ], qs:[
  {q:"My eyes hurt because I ____ (stare) at the screen all day.", a:"have been staring — actividad reciente con resultado visible."},
  {q:"Choose: How long (are you learning / have you been learning) Spanish?", a:"have you been learning — duración hasta ahora."},
  {q:"Correct the mistake: She is working here since 2015.", a:"She has been working here since 2015. — 'since' pide perfecto."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"⚖️", t:"Present Perfect Simple vs Continuous", es:"Perfecto simple vs continuo", d:"Resultado y cantidad frente a duración y actividad en curso.",
 boxes:[
  {e:"🎯", h:"Simple: result", es:"Simple: resultado", i:[["Focus on the completed result: I've painted the kitchen.","Importa el resultado terminado: He pintado la cocina."],["Quantity: I've drunk four cups of tea.","Cantidad: Me he tomado cuatro tés."]], ex:["She's written three emails.","Ha escrito tres correos."]},
  {e:"🔄", h:"Continuous: activity", es:"Continuo: actividad", i:[["Focus on the activity: I've been painting the kitchen.","Importa la actividad: He estado pintando la cocina."],["Duration: We've been walking for two hours.","Duración: Llevamos dos horas caminando."]], ex:["He's been writing all morning.","Ha estado escribiendo toda la mañana."]},
  {e:"🔢", h:"How many / How much", es:"Cantidad", i:[["Simple for quantity: I've read five chapters.","Simple para cantidad: He leído cinco capítulos."],["Continuous for duration: I've been reading for an hour.","Continuo para duración: Llevo una hora leyendo."]], ex:["How many pages have you read?","¿Cuántas páginas has leído?"]},
  {e:"⌛", h:"Temporary vs permanent", es:"Temporal vs permanente", i:[["Continuous: temporary: I've been living in a hotel.","Continuo: temporal: He estado viviendo en un hotel."],["Simple: permanent: I've lived here all my life.","Simple: permanente: He vivido aquí toda mi vida."]], ex:["We've been staying with friends.","Hemos estado alojándonos con amigos."]},
  {e:"✅", h:"Finished or not?", es:"¿Terminado o no?", i:[["Simple: usually complete: I've cleaned the car.","Simple: normalmente terminado: He limpiado el auto."],["Continuous: maybe unfinished: I've been cleaning the car.","Continuo: quizá sin terminar: He estado limpiando el auto."]], ex:["I've been cleaning, so the flat smells nice.","He estado limpiando, así que el apartamento huele bien."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I've been knowing him since school.","✓ I've known him since school. — verbo de estado: simple."],["✗ I've been reading five chapters.","✓ I've read five chapters. — con cantidad, perfecto simple."],["✗ How many time have you been waiting?","✓ How long have you been waiting? — duración: how long."]], ex:["I've owned this bike since 2015.","Tengo esta bici desde 2015."]}
 ], qs:[
  {q:"I ____ (read) this novel for two weeks, and I ____ (read) 200 pages.", a:"have been reading / have read — duración vs cantidad."},
  {q:"Choose: She's (been cooking / cooked) all afternoon, so the kitchen's a mess.", a:"been cooking — actividad con resultado visible."},
  {q:"Correct the mistake: I've been writing three emails this morning.", a:"I've written three emails this morning. — cantidad = perfecto simple."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🆚", t:"Present Perfect vs Past Simple", es:"Pretérito perfecto vs pasado simple", d:"¿Cuándo usar have/has + participio y cuándo el pasado simple?",
 boxes:[
  {e:"✅", h:"Present Perfect", es:"have/has + participio", i:[["Life experience: I have been to Peru.","Experiencia de vida: He estado en Perú."],["Result now: I've lost my keys.","Resultado ahora: He perdido las llaves."]], ex:["She has just left.","Acaba de irse."]},
  {e:"🕰️", h:"Past Simple", es:"Pasado terminado", i:[["Finished time stated: I went to Peru in 2019.","Tiempo terminado y dicho: Fui a Perú en 2019."],["Specific moment: I lost my keys yesterday.","Momento concreto: Perdí las llaves ayer."]], ex:["He left at six.","Se fue a las seis."]},
  {e:"🔔", h:"Signals: Present Perfect", es:"Señales", i:[["ever, never, just, already, yet, so far: I've already eaten.","ever, never, just, already, yet, so far: Ya he comido."],["this week, today (unfinished): I've seen him today.","esta semana, hoy (sin acabar): Lo he visto hoy."]], ex:["Have you ever met anyone famous?","¿Has conocido alguna vez a alguien famoso?"]},
  {e:"📌", h:"Signals: Past Simple", es:"Señales", i:[["yesterday, last year, in 2010, ago: I bought it two weeks ago.","ayer, el año pasado, en 2010, hace: Lo compré hace dos semanas."],["when did...? When did you arrive?","¿cuándo...?: ¿Cuándo llegaste?"]], ex:["We met in 2015.","Nos conocimos en 2015."]},
  {e:"🔀", h:"Switching tenses", es:"Cambio de tiempo", i:[["Experience (PP), then details (PS): I've been to Rome. We stayed for a week.","Experiencia (PP) y luego detalles (PS): He estado en Roma. Nos quedamos una semana."],["News in PP, details in PS: I've lost my phone. I left it on the Tube.","Noticia en PP, detalles en PS: He perdido el celular. Lo dejé en el metro."]], ex:["Have you seen it? Yes, I saw it last night.","¿Lo has visto? Sí, lo vi anoche."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I have seen him yesterday.","✓ I saw him yesterday. — con tiempo terminado, pasado simple."],["✗ When have you arrived?","✓ When did you arrive? — 'when' + pasado simple."],["✗ Did you ever been to Rome?","✓ Have you ever been to Rome? — experiencia: presente perfecto."]], ex:["I've lived here since 2020.","Vivo aquí desde 2020."]}
 ], qs:[
  {q:"I ____ (see) that film last night.", a:"saw — 'last night' exige pasado simple."},
  {q:"Choose: (Have you seen / Did you see) the match last night?", a:"Did you see — 'last night' exige pasado simple."},
  {q:"Correct the mistake: I have bought this jacket two weeks ago.", a:"I bought this jacket two weeks ago. — 'ago' = pasado simple."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"⏪", t:"Past Perfect", es:"Pasado perfecto", d:"Una acción pasada anterior a otra acción también pasada.",
 boxes:[
  {e:"🧱", h:"Form", es:"Forma", i:[["had + past participle: I had finished.","had + participio: Había terminado."],["Negative: She hadn't eaten.","Negativa: No había comido."],["Question: Had they left?","Pregunta: ¿Se habían ido?"]], ex:["He had already gone.","Él ya se había ido."]},
  {e:"1️⃣", h:"Earlier past", es:"Pasado anterior", i:[["First event: past perfect: The film had started","Primer hecho: pasado perfecto: La película había empezado"],["Second event: past simple: ...when we arrived.","Segundo hecho: pasado simple: ...cuando llegamos."]], ex:["When we arrived, the film had started.","Cuando llegamos, la película había empezado."]},
  {e:"🔔", h:"Signal words", es:"Palabras clave", i:[["already, just, before, by the time: By the time I got there, she'd left.","already, just, before, by the time: Cuando llegué, ella ya se había ido."],["after, until: I waited until he'd finished.","after, until: Esperé hasta que terminó."]], ex:["I'd never seen snow before.","Nunca antes había visto nieve."]},
  {e:"🔍", h:"Reasons in the past", es:"Causas", i:[["Explain a past situation: He was late because he'd missed the Tube.","Explicar una situación pasada: Llegó tarde porque había perdido el metro."],["Before another past event: The pitch was wet; it had rained all night.","Antes de otro hecho pasado: El campo estaba mojado; había llovido toda la noche."]], ex:["She was upset because she'd failed her test.","Estaba disgustada porque no había aprobado el examen."]},
  {e:"💭", h:"Reported speech & conditionals", es:"Estilo indirecto y condicionales", i:[["Reported speech: 'I saw him.' → She said she'd seen him.","Estilo indirecto: 'Lo vi.' → Dijo que lo había visto."],["Third conditional: If I'd known, I'd have come.","Tercer condicional: Si lo hubiera sabido, habría venido."]], ex:["He said he had lost his wallet.","Dijo que había perdido la cartera."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ When I arrived, the film started.","✓ When I arrived, the film had started. — empezó antes: pasado perfecto."],["✗ I had went home.","✓ I had gone home. — had + participio (gone)."],["✗ After I had eaten, I have gone out.","✓ After I had eaten, I went out. — el segundo hecho va en pasado simple."]], ex:["Had you met her before the party?","¿La habías conocido antes de la fiesta?"]}
 ], qs:[
  {q:"When I got to the station, the train ____ (already/leave).", a:"had already left — anterior a 'got'."},
  {q:"Choose: After she (had finished / has finished) her homework, she went out.", a:"had finished — anterior a 'went out'; 'has finished' no encaja con un pasado."},
  {q:"Correct the mistake: By the time we arrived, the film already started.", a:"...the film had already started. — hecho anterior: pasado perfecto."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🕰️", t:"Past Perfect Continuous", es:"Pasado perfecto continuo", d:"Duración de una acción que ocurría antes de otro momento del pasado.",
 boxes:[
  {e:"🧱", h:"Form", es:"Forma", i:[["had + been + verb-ing: I had been waiting.","had + been + verbo-ing: Había estado esperando."],["Negative: She hadn't been sleeping.","Negativa: No había estado durmiendo."]], ex:["They had been walking for hours.","Habían estado caminando durante horas."]},
  {e:"⏳", h:"Duration before a past moment", es:"Duración previa", i:[["for / since + past moment: He'd been working there for ten years when he retired.","for / since + momento pasado: Llevaba diez años trabajando allí cuando se jubiló."],["She'd been working there since 2010.","Trabajaba allí desde 2010."]], ex:["I had been waiting for an hour when she arrived.","Llevaba una hora esperando cuando ella llegó."]},
  {e:"🔎", h:"Cause of a past situation", es:"Causa", i:[["Explain visible results: His clothes were wet; he'd been standing in the rain.","Explicar resultados visibles: Tenía la ropa mojada; había estado bajo la lluvia."],["The grass was wet; it had been raining.","La hierba estaba mojada; había estado lloviendo."]], ex:["She was exhausted; she'd been revising all night.","Estaba agotada; había estado estudiando toda la noche."]},
  {e:"⚖️", h:"Past perfect vs continuous", es:"Contraste", i:[["Result: I'd painted the room.","Resultado: Había pintado la habitación."],["Activity: I'd been painting.","Actividad: Había estado pintando."]], ex:["I'd been cooking, so the kitchen was a mess.","Había estado cocinando, así que la cocina era un desastre."]},
  {e:"🔔", h:"Signal words & questions", es:"Palabras clave y preguntas", i:[["for, since, all morning: It had been raining since dawn.","for, since, toda la mañana: Llevaba lloviendo desde el amanecer."],["How long had you been driving?","¿Cuánto tiempo llevabas conduciendo?"]], ex:["How long had she been learning Spanish?","¿Cuánto tiempo llevaba aprendiendo español?"]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I was waiting for an hour when she arrived.","✓ I had been waiting for an hour when she arrived. — duración antes de un momento pasado."],["✗ I'd been knowing her for years.","✓ I'd known her for years. — verbo de estado: sin continuo."],["✗ She had been wait all day.","✓ She had been waiting all day. — been + verbo-ing."]], ex:["He'd had that car for a decade.","Había tenido ese auto durante una década."]}
 ], qs:[
  {q:"By the time the bus came, we ____ (wait) for forty minutes.", a:"had been waiting — duración hasta un momento pasado."},
  {q:"Choose: Her eyes were red because she (had been crying / has been crying).", a:"had been crying — causa anterior a un estado pasado."},
  {q:"Correct the mistake: They had been knowing each other since school.", a:"They had known each other since school. — 'know' es estativo."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🔮", t:"Talking about the Future: will, going to, Present Continuous", es:"Hablar del futuro: will, going to, presente continuo", d:"Decisiones, planes, citas y predicciones: qué forma usar para cada una.",
 boxes:[
  {e:"💡", h:"Will: decisions, promises, offers", es:"Will: decisiones, promesas, ofrecimientos", i:[["Instant decision: The phone's ringing. I'll get it.","Decisión espontánea: Suena el teléfono. Contesto yo."],["Promise: I'll call you tonight.","Promesa: Te llamaré esta noche."],["Offer (British): Shall I open the window?","Ofrecimiento (británico): ¿Abro la ventana?"]], ex:["I'll have the fish, please.","Tomaré el pescado, por favor."]},
  {e:"📝", h:"Going to: plans & evidence", es:"Going to: planes y evidencia", i:[["Plan decided before: I'm going to study law.","Plan decidido antes: Voy a estudiar Derecho."],["Evidence now: Look at those clouds! It's going to rain.","Evidencia ahora: ¡Mira esas nubes! Va a llover."]], ex:["We're going to visit Scotland in August.","Vamos a visitar Escocia en agosto."]},
  {e:"🗓️", h:"Present Continuous: arrangements", es:"Presente continuo: citas", i:[["Fixed arrangement: I'm seeing the dentist on Friday.","Cita fijada: El viernes voy al dentista."],["Time and place decided: We're having dinner at 19:30.","Hora y lugar decididos: Cenamos a las 19:30."],["Arrangement vs intention: I'm seeing Anna tonight. / I'm going to ask her out.","Cita vs intención: Esta noche veo a Anna. / Voy a invitarla a salir."]], ex:["We're flying to Dublin tomorrow.","Mañana volamos a Dublín."]},
  {e:"🌤️", h:"Predictions", es:"Predicciones", i:[["Opinion (will): I think it will be sunny.","Opinión (will): Creo que hará sol."],["Words: probably, perhaps, I'm sure: She'll probably pass.","Palabras: probablemente, quizá, seguro: Probablemente aprobará."],["Evidence (going to): She's pregnant; she's going to have a baby.","Evidencia (going to): Está embarazada; va a tener un bebé."]], ex:["Careful! You're going to fall.","¡Cuidado! Te vas a caer."]},
  {e:"📅", h:"Timetables & time words", es:"Horarios y marcadores", i:[["Timetables: present simple: The train leaves at 09:15.","Horarios: presente simple: El tren sale a las 09:15."],["tonight, next week, at the weekend: We're going out at the weekend.","esta noche, la semana que viene, el fin de semana: Salimos el fin de semana."]], ex:["The match starts at three.","El partido empieza a las tres."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I will go to the dentist tomorrow at five. (already arranged)","✓ I'm going to the dentist tomorrow at five. — cita ya fijada: presente continuo."],["✗ Look at the clouds! It will rain.","✓ ...It's going to rain. — evidencia presente: going to."],["✗ It's raining tomorrow.","✓ It will rain tomorrow. — predicción del tiempo: will / going to, no presente continuo."]], ex:["Shall we meet at the pub at eight?","¿Quedamos en el pub a las ocho?"]}
 ], qs:[
  {q:"'There's no milk.' – 'Oh, I ____ (get) some from the shop.'", a:"'ll get — decisión espontánea."},
  {q:"Choose: We (are having / will have) a party on Saturday. I've sent the invitations.", a:"are having — arreglo ya fijado."},
  {q:"Correct the mistake: I think I go to the cinema tonight. (just decided)", a:"I think I'll go to the cinema tonight. — decisión en el momento: will."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🌅", t:"Future Continuous", es:"Futuro continuo", d:"Acciones en progreso en un momento futuro y preguntas educadas.",
 boxes:[
  {e:"🧱", h:"Form", es:"Forma", i:[["will + be + verb-ing: I'll be working.","will + be + verbo-ing: Estaré trabajando."],["Negative: She won't be sleeping.","Negativa: No estará durmiendo."],["Question: Will you be using the car?","Pregunta: ¿Vas a usar el auto?"]], ex:["This time next week, I'll be lying on a beach.","A esta hora la semana que viene estaré acostado en la playa."]},
  {e:"⏱️", h:"In progress at a future time", es:"En progreso", i:[["At 8 tomorrow, I'll be travelling.","Mañana a las ocho estaré viajando."],["At 6 p.m. I'll be cooking dinner.","A las seis estaré preparando la cena."]], ex:["At noon they'll be sitting an exam.","Al mediodía estarán haciendo un examen."]},
  {e:"🙏", h:"Polite questions", es:"Preguntas educadas", i:[["Asking about plans: Will you be needing the car tonight?","Preguntar por planes: ¿Va a necesitar el auto esta noche?"],["More polite than 'Will you...?': Will you be staying long?","Más cortés que 'Will you...?': ¿Se quedará mucho tiempo?"]], ex:["Will you be having dessert?","¿Va a tomar postre?"]},
  {e:"📋", h:"Future as a matter of course", es:"Hecho previsto", i:[["Something that will happen anyway: I'll be seeing her at work tomorrow.","Algo que ocurrirá de todos modos: La veré en el trabajo mañana."],["Not a decision, just the plan: I'll be seeing Jo on Friday anyway.","No es decisión, es lo previsto: Veré a Jo el viernes de todos modos."]], ex:["I'll be passing the post office, so I'll post it.","Pasaré por la oficina de correos, así que lo enviaré."]},
  {e:"⚖️", h:"vs will", es:"Contraste con will", i:[["I'll call at 8. (action)","Llamaré a las 8. (acción)"],["I'll be eating at 8. (in progress)","A las 8 estaré cenando. (en progreso)"]], ex:["Don't ring at nine; I'll be putting the kids to bed.","No llames a las nueve; estaré acostando a los niños."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ This time tomorrow I'll sit on a plane.","✓ This time tomorrow I'll be sitting on a plane. — acción en progreso: futuro continuo."],["✗ I'll be knowing the results on Friday.","✓ I'll know the results on Friday. — verbo de estado: will + base."],["✗ I will being at home.","✓ I will be at home. — will + be + (verbo-ing)."]], ex:["In July we'll be living in Cardiff.","En julio viviremos en Cardiff."]}
 ], qs:[
  {q:"This time tomorrow I ____ (sit) on a plane to Madrid.", a:"will be sitting — en progreso en un momento futuro."},
  {q:"Choose: This time next week I (lie / will be lying) on a beach in Spain.", a:"will be lying — acción en progreso en un momento futuro."},
  {q:"Correct the mistake: Will you using the car tonight?", a:"Will you be using the car tonight? — falta 'be'."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🏁", t:"Future Perfect", es:"Futuro perfecto", d:"Acciones que estarán terminadas antes de un momento del futuro.",
 boxes:[
  {e:"🧱", h:"Form", es:"Forma", i:[["will + have + past participle: I'll have finished.","will + have + participio: Habré terminado."],["Negative: She won't have arrived.","Negativa: No habrá llegado."],["Question: Will you have left?","Pregunta: ¿Te habrás ido?"]], ex:["By Friday, they'll have moved in.","Para el viernes se habrán mudado."]},
  {e:"⏰", h:"Completed by a time", es:"Terminado antes de", i:[["by + time: I'll have finished by six.","by + hora: Habré terminado a las seis."],["by the time + present simple: By the time you arrive, we'll have eaten.","by the time + presente simple: Para cuando llegues, habremos comido."]], ex:["By 2030 I'll have paid off my mortgage.","Para 2030 habré pagado mi hipoteca."]},
  {e:"🔔", h:"Signal words", es:"Palabras clave", i:[["by, by then, before, by the end of: By the end of the year, I'll have saved £2,000.","by, para entonces, antes de, a finales de: A finales de año habré ahorrado 2.000 libras."],["By then, they'll have left.","Para entonces, se habrán ido."]], ex:["She'll have graduated by next summer.","Se habrá graduado el próximo verano."]},
  {e:"🎂", h:"Milestones", es:"Hitos", i:[["Duration reached: In May we'll have been married for ten years.","Duración alcanzada: En mayo llevaremos diez años casados."],["In June I'll have been teaching for 20 years.","En junio llevaré veinte años enseñando."]], ex:["Next month I'll have worked here for a year.","El mes que viene llevaré un año trabajando aquí."]},
  {e:"🔮", h:"Predictions", es:"Predicciones", i:[["Probably already done: You'll have heard the news by now.","Seguramente ya hecho: Ya habrás oído la noticia."],["He'll have seen my message by now.","Ya habrá visto mi mensaje."]], ex:["They'll have got home by now.","Ya habrán llegado a casa."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ By the time I will get there, they'll have left.","✓ By the time I get there, they'll have left. — sin will tras by the time."],["✗ I'll have finish by six.","✓ I'll have finished by six. — will have + participio."],["✗ She'll has arrived by now.","✓ She'll have arrived by now. — tras will, 'have' (nunca 'has')."]], ex:["Before you wake up, I'll have left.","Antes de que te despiertes, me habré ido."]}
 ], qs:[
  {q:"By next June, she ____ (finish) her degree.", a:"will have finished — completado antes de un punto futuro."},
  {q:"Choose: By the time you (will arrive / arrive), we'll have eaten.", a:"arrive — presente simple tras by the time."},
  {q:"Correct the mistake: I will have wrote the report by Friday.", a:"I will have written the report by Friday. — participio de write: written."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"⏲️", t:"Future Time Clauses (when, as soon as, until)", es:"Oraciones temporales de futuro", d:"Después de when, as soon as o until se usa el presente, no will.",
 boxes:[
  {e:"📏", h:"The rule", es:"La regla", i:[["time word + present simple, will + verb: When I arrive, I'll ring you.","palabra temporal + presente simple, will + verbo: Cuando llegue, te llamaré."],["No will after the time word: I'll wait until you come.","Sin will tras la palabra temporal: Esperaré hasta que vengas."]], ex:["I'll call you as soon as I get home.","Te llamaré en cuanto llegue a casa."]},
  {e:"🔗", h:"Time words", es:"Conectores", i:[["when, as soon as, until, before, after: I'll wait until you finish.","when, as soon as, until, before, after: Esperaré hasta que termines."],["by the time, once, while: Once I've eaten, I'll go out.","by the time, once, while: Una vez que haya comido, saldré."]], ex:["Let's go after we've had a cup of tea.","Vámonos después de tomar un té."]},
  {e:"✅", h:"Present perfect option", es:"Con presente perfecto", i:[["Emphasise completion: I'll phone you when I've finished.","Para enfatizar que se ha completado: Te llamaré cuando haya terminado."],["After + present perfect: I'll go after I've finished.","After + presente perfecto: Iré después de haber terminado."]], ex:["We'll leave as soon as it has stopped raining.","Saldremos en cuanto haya parado de llover."]},
  {e:"❓", h:"If clauses are similar", es:"Similar con if", i:[["If + present, will + verb: If it rains, we'll stay in.","If + presente, will + verbo: Si llueve, nos quedaremos en casa."],["Unless = if not: Unless it rains, we'll have a picnic.","Unless = if not: A menos que llueva, haremos un pícnic."]], ex:["If you're late, I'll start without you.","Si llegas tarde, empezaré sin ti."]},
  {e:"🔄", h:"Order can change", es:"El orden cambia", i:[["No comma in second position: I'll text you when I arrive.","Sin coma si va en segundo lugar: Te escribiré cuando llegue."],["Comma in first position: When I arrive, I'll text you.","Con coma si va primero: Cuando llegue, te escribiré."]], ex:["Before you leave, remember your coat.","Antes de irte, acuérdate del abrigo."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ When I will arrive, I'll ring you.","✓ When I arrive, I'll ring you. — presente, no will, tras when."],["✗ I'll wait until he will come.","✓ I'll wait until he comes. — presente simple tras until."],["✗ If it will rain, we'll stay in.","✓ If it rains, we'll stay in. — igual con if."]], ex:["I'll stay here until the bus comes.","Me quedaré aquí hasta que venga el autobús."]}
 ], qs:[
  {q:"I'll phone you as soon as I ____ (arrive) at the hotel.", a:"arrive — presente simple tras as soon as."},
  {q:"Choose: I'll make dinner when you (will get / get) home.", a:"get — presente simple tras when."},
  {q:"Correct the mistake: We'll go out after it will stop raining.", a:"...after it stops raining. — sin will tras after."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"👴", t:"Used to & Would (Past Habits)", es:"Used to y would (hábitos pasados)", d:"Hábitos y estados del pasado que ya no se dan.",
 boxes:[
  {e:"🧱", h:"Used to: form", es:"Forma", i:[["used to + base verb: I used to smoke.","used to + verbo base: Yo solía fumar."],["Negative: She didn't use to like tea.","Negativa: Antes no le gustaba el té."],["Question: Did you use to live here?","Pregunta: ¿Vivías aquí antes?"]], ex:["We used to go to Brighton every summer.","Solíamos ir a Brighton cada verano."]},
  {e:"🏡", h:"Past states", es:"Estados pasados", i:[["Used to also works for states: He used to have long hair.","Used to también sirve para estados: Antes tenía el pelo largo."],["Used to + be/have/know/live: We used to live in Hull.","Used to + be/have/know/live: Antes vivíamos en Hull."]], ex:["This pub used to be a bank.","Este pub solía ser un banco."]},
  {e:"🔁", h:"Past habits", es:"Hábitos", i:[["Used to and would both work: We would play football every Saturday.","Used to y would sirven: Jugábamos al fútbol cada sábado."],["Would + repeated actions: He would ring me every night.","Would + acciones repetidas: Me llamaba todas las noches."]], ex:["Every Sunday, Gran would make a roast.","Cada domingo la abuela hacía un asado."]},
  {e:"🚫", h:"Would: restriction", es:"Restricción de would", i:[["Not for states: I used to have a dog. (not would have)","No para estados: Tenía un perro. (no 'would have')"],["I used to know him. (not would know)","Lo conocía. (no 'would know')"]], ex:["I used to be shy.","Yo solía ser tímido."]},
  {e:"🔄", h:"Not for single events", es:"No para hechos únicos", i:[["Use past simple: I went to Spain in 2019. (not used to)","Usa el pasado simple: Fui a España en 2019. (no 'used to')"],["I moved to London in 2018.","Me mudé a Londres en 2018."]], ex:["I broke my leg last winter.","Me rompí la pierna el invierno pasado."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Did you used to smoke?","✓ Did you use to smoke? — tras did, 'use to' sin d."],["✗ I use to play tennis as a child.","✓ I used to play tennis as a child. — pasado: 'used to'."],["✗ I would be shy when I was young.","✓ I used to be shy when I was young. — estado: used to, no would."]], ex:["I didn't use to like olives.","Antes no me gustaban las aceitunas."]}
 ], qs:[
  {q:"Complete: When I was a child, we ____ (live) in a small village.", a:"used to live — estado pasado (would no es adecuado)."},
  {q:"Which sentence can't use 'would' instead of 'used to'? (a) We used to go to Cornwall every summer. (b) We used to have a caravan in Cornwall.", a:"b — 'have' (poseer) es un estado; en (a) sí se puede usar would."},
  {q:"Correct the mistake: She didn't used to like coffee.", a:"She didn't use to like coffee. — tras didn't, 'use to'."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🌱", t:"Be Used To vs Get Used To", es:"Estar acostumbrado vs acostumbrarse", d:"Diferencia entre un estado de costumbre y el proceso de adaptación.",
 boxes:[
  {e:"✅", h:"Be used to", es:"Estar acostumbrado", i:[["be used to + noun/-ing: I'm used to the weather.","be used to + nombre/-ing: Estoy acostumbrado al clima."],["= familiar, not strange: She's used to driving on the left.","= familiar, no extraño: Está acostumbrada a conducir por la izquierda."]], ex:["I'm used to getting up early.","Estoy acostumbrado a madrugar."]},
  {e:"📈", h:"Get used to", es:"Acostumbrarse", i:[["Process of becoming used to: I'm getting used to the food.","Proceso de acostumbrarse: Me estoy acostumbrando a la comida."],["Get used to + noun / -ing: I can't get used to the cold.","Get used to + nombre / -ing: No me acostumbro al frío."]], ex:["You'll soon get used to the Tube.","Pronto te acostumbrarás al metro."]},
  {e:"🕰️", h:"Tenses", es:"Tiempos", i:[["I was used to...: I was used to the noise.","Estaba acostumbrado a...: Estaba acostumbrado al ruido."],["I'll get used to...: I'll get used to it.","Me acostumbraré a...: Me acostumbraré."]], ex:["I got used to driving on the left.","Me acostumbré a conducir por la izquierda."]},
  {e:"🔀", h:"Not the same as 'used to'", es:"No confundir con used to", i:[["used to + verb = past habit: I used to walk to school.","used to + verbo = hábito pasado: Iba caminando al colegio."],["be used to + -ing: I'm used to walking.","be used to + -ing: Estoy acostumbrado a caminar."]], ex:["I used to hate mornings, but now I'm used to them.","Antes odiaba las mañanas, pero ahora estoy acostumbrado."]},
  {e:"❌", h:"Negative", es:"Negativa", i:[["I'm not used to...: I'm not used to spicy food.","No estoy acostumbrado a...: No estoy acostumbrado a la comida picante."],["I can't get used to...: I can't get used to the noise.","No consigo acostumbrarme a...: No consigo acostumbrarme al ruido."]], ex:["He isn't used to living alone.","No está acostumbrado a vivir solo."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I'm used to work nights.","✓ I'm used to working nights. — be used to + -ing, no verbo base."],["✗ I'm used to get up early.","✓ I'm used to getting up early. — tras 'to' preposición, -ing."],["✗ I'm getting use to the weather.","✓ I'm getting used to the weather. — 'used' con -d."]], ex:["She's used to working nights.","Está acostumbrada a trabajar de noche."]}
 ], qs:[
  {q:"After a month in Glasgow, I'm finally ____ (get used) to the accent.", a:"getting used — proceso de adaptación."},
  {q:"Choose: I'm not used (to drive / to driving) on the left.", a:"to driving — be used to + -ing."},
  {q:"Correct the mistake: When I was young, I was used to play in the street.", a:"I used to play in the street. — hábito pasado, 'used to' + base."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"💪", t:"Modals of Ability", es:"Modales de habilidad", d:"Can, could y be able to para hablar de lo que se puede o se pudo hacer.",
 boxes:[
  {e:"🟢", h:"Can: present", es:"Habilidad presente", i:[["can + base verb: I can swim.","can + verbo base: Sé nadar."],["Negative: can't / cannot: She can't drive.","Negativa: can't / cannot: Ella no sabe conducir."]], ex:["Can you speak French?","¿Hablas francés?"]},
  {e:"⏪", h:"Could: general past", es:"Habilidad pasada general", i:[["could = general ability: I could read at four.","could = habilidad general: Sabía leer a los cuatro años."],["Negative: I couldn't swim until I was ten.","Negativa: No sabía nadar hasta los diez."]], ex:["He couldn't ride a bike as a child.","De niño no sabía andar en bicicleta."]},
  {e:"🎯", h:"Was able to: one occasion", es:"Una ocasión concreta", i:[["was/were able to = succeeded: I was able to fix it.","was/were able to = lograr: Pude arreglarlo."],["Not 'could' for one success: We managed to get tickets.","No 'could' para un logro puntual: Conseguimos entradas."]], ex:["Luckily, they were able to find a flat.","Por suerte, pudieron encontrar un apartamento."]},
  {e:"🔮", h:"Be able to: other forms", es:"Otras formas", i:[["will be able to: I'll be able to help tomorrow.","will be able to: Mañana podré ayudar."],["have been able to: I haven't been able to sleep.","have been able to: No he podido dormir."]], ex:["You'll be able to vote at eighteen.","Podrás votar a los dieciocho."]},
  {e:"✨", h:"Managed to / succeeded in", es:"Conseguir", i:[["managed to + verb: I managed to catch the train.","managed to + verbo: Conseguí alcanzar el tren."],["succeeded in + -ing: She succeeded in passing.","succeeded in + -ing: Consiguió aprobar."]], ex:["He managed to open the door.","Consiguió abrir la puerta."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I can to swim.","✓ I can swim. — can + verbo base, sin 'to'."],["✗ She cans drive.","✓ She can drive. — can no lleva -s."],["✗ Yesterday I could pass the exam. (one success)","✓ Yesterday I was able to / managed to pass the exam. — logro puntual: was able to."]], ex:["I can't hear you; the line's bad.","No te oigo; la línea es mala."]}
 ], qs:[
  {q:"Yesterday I was ill, but I ____ (manage) to finish the report.", a:"managed — logro concreto en una ocasión (managed to / was able to)."},
  {q:"Choose: When I was five, I (could / managed to) read already.", a:"could — habilidad general en el pasado (managed to = logro puntual)."},
  {q:"Correct the mistake: He can to speak three languages.", a:"He can speak three languages. — sin 'to' tras can."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🚦", t:"Modals of Obligation & Prohibition", es:"Modales de obligación y prohibición", d:"Must, have to, mustn't y don't have to: diferencias clave.",
 boxes:[
  {e:"📌", h:"Must", es:"Obligación personal", i:[["Speaker's own feeling: I must call my mum.","Sentimiento del hablante: Tengo que llamar a mi madre."],["Written rules: Visitors must sign in.","Normas escritas: Los visitantes deben registrarse."]], ex:["You must wear a seatbelt.","Debes llevar el cinturón."]},
  {e:"📋", h:"Have to", es:"Obligación externa", i:[["Rules or external duty: I have to wear a uniform.","Normas u obligación externa: Tengo que llevar uniforme."],["Questions: Do we have to pay?","Preguntas: ¿Tenemos que pagar?"]], ex:["Young people in England have to stay in education or training until eighteen.","En Inglaterra, los jóvenes tienen que seguir estudiando o formándose hasta los dieciocho."]},
  {e:"⛔", h:"Mustn't", es:"Prohibición", i:[["Not allowed: You mustn't park here.","Prohibido: No debes estacionar aquí."],["Mustn't ≠ don't have to: You mustn't smoke here.","Mustn't ≠ don't have to: No debes fumar aquí."]], ex:["You mustn't use your mobile in the exam.","No debes usar el celular en el examen."]},
  {e:"🆓", h:"Don't have to", es:"No es necesario", i:[["Not necessary: You don't have to come.","No es necesario: No tienes que venir."],["= needn't: You needn't wait.","= needn't: No hace falta que esperes."]], ex:["You don't have to pay; it's free.","No tienes que pagar; es gratis."]},
  {e:"⏳", h:"Past & future", es:"Pasado y futuro", i:[["had to (past): I had to leave early.","had to (pasado): Tuve que irme pronto."],["will have to (future): You'll have to queue.","will have to (futuro): Tendrás que hacer cola."]], ex:["We had to wait an hour for the bus.","Tuvimos que esperar el autobús una hora."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ You mustn't come if you don't want to.","✓ You don't have to come if you don't want to. — no es necesario ≠ prohibido."],["✗ I must to go now.","✓ I must go now. — must + verbo base."],["✗ Yesterday I must work late.","✓ Yesterday I had to work late. — must no tiene pasado: had to."]], ex:["Pupils aren't allowed to wear trainers.","No se permite a los alumnos llevar zapatillas deportivas."]}
 ], qs:[
  {q:"You ____ bring your passport, but you ____ bring a pen — we'll give you one. (must / don't have to / mustn't)", a:"must / don't have to — obligación vs no necesidad."},
  {q:"Choose: You (mustn't / don't have to) smoke in the hospital.", a:"mustn't — prohibición."},
  {q:"Correct the mistake: Last week I must go to the dentist.", a:"Last week I had to go to the dentist. — pasado de must: had to."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"👍", t:"Modals of Advice (should, ought to, had better)", es:"Modales de consejo", d:"Cómo dar consejos con distinta fuerza: should, ought to y had better.",
 boxes:[
  {e:"💬", h:"Should", es:"Consejo general", i:[["should + base verb: You should see a doctor.","should + verbo base: Deberías ir al médico."],["Negative: You shouldn't eat so much.","Negativa: No deberías comer tanto."]], ex:["I think you should apologise.","Creo que deberías disculparte."]},
  {e:"👌", h:"Ought to", es:"Más formal", i:[["ought to + base verb: You ought to rest.","ought to + verbo base: Deberías descansar."],["Negative (formal): You ought not to be late.","Negativa (formal): No deberías llegar tarde."]], ex:["We ought to tell the council.","Deberíamos informar a la municipalidad."]},
  {e:"🚨", h:"Had better", es:"Consejo fuerte", i:[["had better + base verb: You'd better hurry.","had better + verbo base: Más te vale apurarte."],["Suggests a risk: You'd better not be late.","Sugiere un riesgo: Más te vale no llegar tarde."]], ex:["We'd better take an umbrella.","Más nos vale llevar paraguas."]},
  {e:"❓", h:"Asking for advice", es:"Pedir consejo", i:[["What should I do?","¿Qué debería hacer?"],["Do you think I should resign?","¿Crees que debería renunciar?"]], ex:["Should I take the job in Leeds?","¿Debería aceptar el trabajo en Leeds?"]},
  {e:"🔙", h:"Should have", es:"Reproche pasado", i:[["should have + pp: You should have rung me.","should have + pp: Deberías haberme llamado."],["shouldn't have + pp: You shouldn't have said that.","shouldn't have + pp: No deberías haber dicho eso."]], ex:["I should have revised more.","Debería haber estudiado más."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ You should to see a doctor.","✓ You should see a doctor. — sin 'to' tras should."],["✗ You had better to go.","✓ You had better go. — 'had better' + verbo base."],["✗ You don't should smoke here.","✓ You shouldn't smoke here. — should no usa do/don't: se niega con shouldn't."]], ex:["If I were you, I'd wear a coat.","Yo que tú, me pondría un abrigo."]}
 ], qs:[
  {q:"It's freezing. You ____ wear a coat. (had better / should have)", a:"had better — consejo fuerte: 'You'd better wear a coat'."},
  {q:"Choose: You (ought / should) to see a GP about that cough.", a:"ought — ought + to + verbo base."},
  {q:"Correct the mistake: You shouldn't to eat so much sugar.", a:"You shouldn't eat so much sugar. — sin 'to'."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🕵️", t:"Modals of Deduction (Present)", es:"Modales de deducción (presente)", d:"Must, might, could y can't para deducir algo sobre el presente.",
 boxes:[
  {e:"💯", h:"Must: sure it's true", es:"Casi seguro", i:[["must + base verb: He must be tired.","must + verbo base: Debe de estar cansado."],["Also must have + noun: He must have a lot of money.","También must have + nombre: Debe de tener mucho dinero."]], ex:["She's got a Rolex; she must be rich.","Tiene un Rolex; debe de ser rica."]},
  {e:"🚫", h:"Can't: sure it's false", es:"Imposible", i:[["can't + base verb: That can't be right.","can't + verbo base: Eso no puede estar bien."],["That can't be his car.","Ese no puede ser su auto."]], ex:["He can't be at work; it's Sunday.","No puede estar en el trabajo; es domingo."]},
  {e:"🤷", h:"Might / may / could", es:"Posible", i:[["might + base verb: She might be at home.","might + verbo base: Puede que esté en casa."],["could / may: It could be a fox.","could / may: Podría ser un zorro."]], ex:["They might be stuck in traffic.","Quizá estén atrapados en el tráfico."]},
  {e:"⏱️", h:"Continuous forms", es:"Forma continua", i:[["must be + -ing: He must be working late.","must be + -ing: Debe de estar trabajando hasta tarde."],["might be + -ing: She might be sleeping.","might be + -ing: Puede que esté durmiendo."]], ex:["The lights are on; they must be having dinner.","Las luces están encendidas; deben de estar cenando."]},
  {e:"📊", h:"Certainty scale", es:"Escala", i:[["must ≈ 95%: He must be ill.","must ≈ 95%: Debe de estar enfermo."],["might ≈ 50%: He might be ill.","might ≈ 50%: Quizá esté enfermo."],["can't ≈ 0%: He can't be ill.","can't ≈ 0%: No puede estar enfermo."]], ex:["She might know the answer.","Puede que sepa la respuesta."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ That mustn't be true.","✓ That can't be true. — deducción negativa: can't, no mustn't."],["✗ He must to be tired.","✓ He must be tired. — sin 'to'."],["✗ She must being at home.","✓ She must be at home. — tras must, verbo base 'be' (no 'being')."]], ex:["That can't be true!","¡Eso no puede ser verdad!"]}
 ], qs:[
  {q:"Tom's car is outside, so he ____ be at home. (must / can't)", a:"must — deducción positiva fuerte."},
  {q:"Choose: She's been on holiday for a week, so she (must / can't) be at work.", a:"can't — imposible."},
  {q:"Correct the mistake: He isn't answering. He mustn't be at home.", a:"He can't be at home. — deducción negativa."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🔍", t:"Modals of Deduction (Past)", es:"Modales de deducción (pasado)", d:"Must have, can't have y might have para deducir sobre el pasado.",
 boxes:[
  {e:"💯", h:"Must have + pp", es:"Seguro que pasó", i:[["must have + past participle: He must have forgotten.","must have + participio: Debe de haberse olvidado."],["Evidence in the present: He's not here; he must have left.","Con pruebas en el presente: No está aquí; debe de haberse ido."]], ex:["The ground is wet; it must have rained.","El suelo está mojado; debe de haber llovido."]},
  {e:"🚫", h:"Can't have + pp", es:"Imposible que pasara", i:[["can't have + pp: She can't have seen us.","can't have + pp: No puede habernos visto."],["couldn't have + pp: They couldn't have known.","couldn't have + pp: No pudieron haberlo sabido."]], ex:["He can't have left; his coat's here.","No puede haberse ido; su abrigo está aquí."]},
  {e:"🤔", h:"Might/may/could have + pp", es:"Posible", i:[["might have + pp: She might have missed the train.","might have + pp: Puede que haya perdido el tren."],["could have + pp: He could have got lost.","could have + pp: Podría haberse perdido."]], ex:["They may have taken a different route.","Puede que hayan tomado otra ruta."]},
  {e:"⏳", h:"Continuous past", es:"Forma continua", i:[["must have been + -ing: She must have been sleeping.","must have been + -ing: Debía de estar durmiendo."],["They must have been waiting for ages.","Deben de haber estado esperando siglos."]], ex:["He didn't answer; he might have been driving.","No contestó; quizá estaba conduciendo."]},
  {e:"⚖️", h:"Deduction vs criticism", es:"Deducción vs reproche", i:[["should have + pp = criticism: You should have called.","should have + pp = reproche: Deberías haber llamado."],["must have + pp = deduction: You must have called.","must have + pp = deducción: Debes de haber llamado."]], ex:["You could have told me!","¡Podrías habérmelo dicho!"]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ She mustn't have seen us.","✓ She can't have seen us. — deducción negativa pasada: can't have."],["✗ He must have forget.","✓ He must have forgotten. — must have + participio."],["✗ They must to have left.","✓ They must have left. — sin 'to'."]], ex:["She must've got lost.","Debe de haberse perdido."]}
 ], qs:[
  {q:"The window's broken. Someone ____ (break) in last night.", a:"must have broken — deducción fuerte sobre el pasado."},
  {q:"Choose: He (can't have / mustn't have) passed — he never revised!", a:"can't have — imposible, deducción negativa."},
  {q:"Correct the mistake: The streets are wet. It must rained.", a:"It must have rained. — falta 'have' + participio."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🙋", t:"Requests, Offers & Suggestions", es:"Peticiones, ofrecimientos y sugerencias", d:"Shall, could y would para pedir, ofrecer y sugerir con cortesía.",
 boxes:[
  {e:"🙏", h:"Polite requests", es:"Peticiones", i:[["Could you...? Could you open the window?","¿Podrías...? ¿Podrías abrir la ventana?"],["Would you mind + -ing? Would you mind waiting?","¿Te importaría + -ing? ¿Te importaría esperar?"]], ex:["Could I have a glass of water, please?","¿Podría darme un vaso de agua, por favor?"]},
  {e:"💬", h:"Informal requests", es:"Informales", i:[["Can you...? Can you pass the milk?","¿Puedes...? ¿Me pasas la leche?"],["Can I borrow...? Can I borrow your pen?","¿Me prestas...? ¿Me prestas tu bolígrafo?"]], ex:["Can you give me a hand?","¿Me echas una mano?"]},
  {e:"🎁", h:"Offers with shall", es:"Ofrecer con shall", i:[["Shall I + verb? Shall I carry that?","Shall I + verbo: ¿Te lo llevo?"],["I'll...: I'll make you a cuppa.","I'll...: Te preparo un té."]], ex:["Shall I put the kettle on?","¿Pongo agua a hervir?"]},
  {e:"🍽️", h:"Offers with would", es:"Ofrecer con would", i:[["Would you like...? Would you like a biscuit?","¿Te gustaría...? ¿Te gustaría una galleta?"],["Would you like me to...? Would you like me to help?","¿Quieres que...? ¿Quieres que te ayude?"]], ex:["Would you like some tea or coffee?","¿Quiere té o café?"]},
  {e:"💡", h:"Suggestions", es:"Sugerencias", i:[["Shall we...? Shall we go to the pub?","¿Vamos a...? ¿Vamos al pub?"],["Let's / Why don't we...? Why don't we get a takeaway?","Vamos a / ¿Por qué no...? ¿Por qué no pedimos comida para llevar?"]], ex:["How about going to the cinema?","¿Y si vamos al cine?"]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ Do you want that I help you?","✓ Would you like me to help you? — 'want that' no existe en inglés."],["✗ Would you mind to wait?","✓ Would you mind waiting? — mind + -ing."],["✗ Do I open the window? (offer)","✓ Shall I open the window? — ofrecimiento: shall I."]], ex:["Shall I help? – That would be lovely, thanks.","¿Te ayudo? – Estaría genial, gracias."]}
 ], qs:[
  {q:"It's hot in here. ____ I open the window? (Shall / Will)", a:"Shall — ofrecimiento con 'I' en inglés británico."},
  {q:"Choose: (Would you mind to / Would you mind) closing the door?", a:"Would you mind — seguido de -ing (closing)."},
  {q:"Correct the mistake: Why we don't go to the cinema tonight?", a:"Why don't we go to the cinema tonight? — orden: Why don't we...?"}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B1", icon:"🔧", t:"The Passive", es:"La voz pasiva", d:"Pasiva en presente, pasado, perfecto, continuo, futuro y con verbos modales.",
 boxes:[
  {e:"🧱", h:"Present & past", es:"Presente y pasado", i:[["am/is/are + pp: English is spoken here.","am/is/are + participio: Aquí se habla inglés."],["was/were + pp: The bridge was built in 1890.","was/were + participio: El puente se construyó en 1890."]], ex:["The letters were delivered yesterday.","Las cartas se entregaron ayer."]},
  {e:"⏳", h:"Perfect & continuous", es:"Perfecto y continuo", i:[["has/have been + pp: Our flights have been cancelled.","has/have been + pp: Nuestros vuelos han sido cancelados."],["is/are being + pp: The new library is being built.","is/are being + pp: Se está construyendo la biblioteca nueva."],["had been + pp: The room had been cleaned.","had been + pp: La habitación había sido limpiada."]], ex:["The roof was being repaired when it rained.","Estaban reparando el tejado cuando llovió."]},
  {e:"🔮", h:"Future & modals", es:"Futuro y modales", i:[["will be + pp: The results will be announced.","will be + pp: Se anunciarán los resultados."],["modal + be + pp: Passports must be shown.","modal + be + pp: Hay que mostrar los pasaportes."],["modal + have been + pp: It should have been done.","modal + have been + pp: Debería haberse hecho."]], ex:["The match will be shown on BBC One.","El partido se emitirá en BBC One."]},
  {e:"🎯", h:"When to use it", es:"Cuándo usarla", i:[["Agent unknown or unimportant: My bike was stolen.","Agente desconocido o poco importante: Me robaron la bicicleta."],["Add by when it matters: Hamlet was written by Shakespeare.","Añade by cuando importa: Hamlet fue escrito por Shakespeare."]], ex:["The Houses of Parliament were designed by Barry.","Las Casas del Parlamento fueron diseñadas por Barry."]},
  {e:"🔄", h:"Active to passive", es:"De activa a pasiva", i:[["Object becomes subject: They repair cars. → Cars are repaired.","El objeto pasa a sujeto: Reparan autos. → Se reparan autos."],["Negative/question: Was it cancelled? It wasn't finished.","Negativa/pregunta: ¿Fue cancelado? No estaba terminado."]], ex:["Someone broke the window. → The window was broken.","Alguien rompió la ventana. → La ventana fue rota."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ The window broke by a boy.","✓ The window was broken by a boy. — pasiva: be + participio."],["✗ The house was build in 1900.","✓ The house was built in 1900. — participio, no base."],["✗ My bike has stolen.","✓ My bike has been stolen. — presente perfecto pasivo: have/has been + participio."]], ex:["When was the Tube opened?","¿Cuándo se inauguró el metro?"]}
 ], qs:[
  {q:"Rewrite: Someone stole my mobile. → My mobile ____.", a:"was stolen — pasiva en pasado simple."},
  {q:"Choose: A new hospital (is building / is being built) in our town.", a:"is being built — pasiva en presente continuo."},
  {q:"Correct the mistake: The rooms are clean every day by the staff.", a:"The rooms are cleaned every day by the staff. — be + participio (cleaned)."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"💇", t:"Causative: have/get something done", es:"Causativa: have/get something done", d:"Para hablar de servicios que otra persona hace por nosotros.",
 boxes:[
  {e:"🧱", h:"Form", es:"Forma", i:[["have + object + past participle: I had my hair cut.","have + objeto + participio: Me corté el pelo (en la peluquería)."],["get + object + pp (informal): I got my car fixed.","get + objeto + pp (informal): Me arreglaron el auto."]], ex:["We're having the kitchen painted.","Nos están pintando la cocina."]},
  {e:"🛠️", h:"Services", es:"Servicios", i:[["have my eyes tested: I had my eyes tested.","hacerme una revisión de la vista: Me revisaron la vista."],["have the boiler serviced: We had the boiler serviced.","revisar la caldera: Nos revisaron la caldera."]], ex:["She has her nails done every month.","Se hace las uñas cada mes."]},
  {e:"⏳", h:"Tenses", es:"Tiempos", i:[["Past: He had his phone repaired.","Pasado: Le repararon el celular."],["Future: I'll have it cleaned.","Futuro: Haré que lo limpien."],["Perfect: I've had it checked.","Perfecto: Lo he mandado revisar."]], ex:["I'm going to have my passport renewed.","Voy a renovar el pasaporte."]},
  {e:"❓", h:"Questions", es:"Preguntas", i:[["Do you often have your car washed?","¿Sueles llevar el auto a lavar?"],["Where did you have it done?","¿Dónde te lo hicieron?"]], ex:["Where did you have your hair cut?","¿Dónde te cortaste el pelo?"]},
  {e:"😞", h:"Bad experiences", es:"Experiencias negativas", i:[["have + object + pp (unwanted): He had his wallet stolen.","have + objeto + pp (no deseado): Le robaron la cartera."],["Same pattern, not our fault: She had her bag stolen.","Mismo patrón, no es culpa nuestra: Le robaron el bolso."]], ex:["We had our flat broken into.","Nos entraron a robar en el apartamento."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ I cut my hair at the hairdresser's.","✓ I had my hair cut at the hairdresser's. — lo hace otro: have + pp."],["✗ I had cut my hair yesterday by the barber.","✓ I had my hair cut by the barber yesterday. — el objeto va entre have y el participio."],["✗ She has her car wash every week.","✓ She has her car washed every week. — participio (washed)."]], ex:["I had the lift fixed last week.","Arreglaron el ascensor la semana pasada."]}
 ], qs:[
  {q:"I can't cut my own hair, so I ____ it ____ (cut) every six weeks.", a:"have / cut — 'have + objeto + participio'."},
  {q:"Choose: We (painted / had painted / had the house painted) last month by a decorator.", a:"had the house painted — lo hizo otra persona."},
  {q:"Correct the mistake: I must get repaired my phone.", a:"I must get my phone repaired. — get + objeto + participio."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"💬", t:"Reported Speech: Statements", es:"Estilo indirecto: afirmaciones", d:"Cómo contar lo que alguien dijo cambiando tiempos y expresiones.",
 boxes:[
  {e:"⬅️", h:"Backshift", es:"Retroceso de tiempos", i:[["Present simple → past simple: 'I work.' → She said she worked.","Presente simple → pasado simple: 'Trabajo.' → Dijo que trabajaba."],["Present continuous → past continuous: 'I'm busy.' → He said he was busy.","Presente continuo → pasado continuo: 'Estoy ocupado.' → Dijo que estaba ocupado."]], ex:["'I like London.' → She said she liked London.","'Me gusta Londres.' → Dijo que le gustaba Londres."]},
  {e:"⏪", h:"More backshifts", es:"Más cambios", i:[["Present perfect/past simple → past perfect: 'I've finished.' → He said he'd finished.","Perfecto/pasado simple → pasado perfecto: 'He terminado.' → Dijo que había terminado."],["will → would: 'I'll call.' → She said she'd call.","will → would: 'Llamaré.' → Dijo que llamaría."]], ex:["'I saw him.' → He said he had seen him.","'Lo vi.' → Dijo que lo había visto."]},
  {e:"🧩", h:"Modals", es:"Modales", i:[["can → could: 'I can swim.' → He said he could swim.","can → could: 'Sé nadar.' → Dijo que sabía nadar."],["must → had to: 'I must go.' → She said she had to go.","must → had to: 'Debo irme.' → Dijo que tenía que irse."]], ex:["'I may be late.' → He said he might be late.","'Puede que llegue tarde.' → Dijo que quizá llegara tarde."]},
  {e:"📍", h:"Time & place words", es:"Tiempo y lugar", i:[["now → then; today → that day","ahora → entonces; hoy → ese día"],["tomorrow → the next day; here → there","mañana → al día siguiente; aquí → allí"]], ex:["'I'll see you tomorrow.' → She said she'd see me the next day.","'Te veré mañana.' → Dijo que me vería al día siguiente."]},
  {e:"🛑", h:"No backshift", es:"Sin retroceso", i:[["Still true / said recently: She said she lives in Leeds.","Sigue siendo cierto / dicho hace poco: Dijo que vive en Leeds."],["Past perfect stays: 'He had left.' → She said he had left.","El pasado perfecto no cambia: 'Se había ido.' → Dijo que se había ido."]], ex:["He said the Earth goes round the Sun.","Dijo que la Tierra gira alrededor del Sol."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ She said me she was tired.","✓ She told me she was tired. — tell + persona; say sin persona."],["✗ He said me that he'd come.","✓ He said (that) he'd come. — 'say' no lleva complemento de persona."],["✗ He said he has seen the film last week.","✓ He said he had seen the film the week before. — retroceso (had seen) y 'last week' → 'the week before'."]], ex:["She told us she was leaving.","Nos dijo que se marchaba."]}
 ], qs:[
  {q:"'I'm going to leave tomorrow,' she said. → She said she ____ (be going to) leave the next day.", a:"was going to — retroceso + cambio de tiempo."},
  {q:"Choose: He (said / told) me that he was tired.", a:"told — tell + persona."},
  {q:"Correct the mistake: 'I have finished,' he said. → He said he has finished.", a:"He said he had finished. — presente perfecto → pasado perfecto."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"❓", t:"Reported Questions & Commands", es:"Preguntas y órdenes indirectas", d:"Cómo transmitir preguntas, órdenes y peticiones de otra persona.",
 boxes:[
  {e:"🔠", h:"Wh- questions", es:"Preguntas con wh-", i:[["Wh- word + statement order: 'Where do you live?' → He asked where I lived.","Palabra wh- + orden afirmativo: '¿Dónde vives?' → Preguntó dónde vivía."],["Where / who / why: He asked who I was.","Where / who / why: Preguntó quién era yo."]], ex:["She asked me what time the train left.","Me preguntó a qué hora salía el tren."]},
  {e:"✅", h:"Yes/No questions", es:"Preguntas sí/no", i:[["if / whether + statement order: 'Are you tired?' → She asked if I was tired.","if / whether + orden afirmativo: '¿Estás cansado?' → Preguntó si estaba cansado."],["Use if or whether: I asked whether it was open.","Usa if o whether: Pregunté si estaba abierto."]], ex:["He asked whether I had a car.","Preguntó si tenía auto."]},
  {e:"📣", h:"Commands", es:"Órdenes", i:[["told + object + to + verb: 'Sit down!' → He told me to sit down.","told + objeto + to + verbo: '¡Siéntate!' → Me dijo que me sentara."],["Negative: 'Don't touch.' → She told us not to touch.","Negativa: 'No toquen.' → Nos dijo que no tocáramos."]], ex:["The teacher told us to be quiet.","La profesora nos dijo que nos calláramos."]},
  {e:"🙏", h:"Requests", es:"Peticiones", i:[["asked + object + to + verb: 'Could you help?' → He asked me to help.","asked + objeto + to + verbo: '¿Podrías ayudar?' → Me pidió que ayudara."],["Negative: He asked me not to tell anyone.","Negativa: Me pidió que no se lo dijera a nadie."]], ex:["She asked me to open the window.","Me pidió que abriera la ventana."]},
  {e:"🔙", h:"Backshift & punctuation", es:"Tiempos y puntuación", i:[["Backshift as in statements: 'Can you swim?' → He asked if I could swim.","Retroceso como en afirmaciones: '¿Sabes nadar?' → Preguntó si sabía nadar."],["No question mark: He asked where I was.","Sin signo de interrogación: Preguntó dónde estaba."]], ex:["He asked me if I had been to Wales.","Me preguntó si había estado en Gales."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ He asked me where did I live.","✓ He asked me where I lived. — sin do/did ni inversión."],["✗ She asked me do I like tea.","✓ She asked me if I liked tea. — preguntas sí/no: if/whether."],["✗ He told me close the door.","✓ He told me to close the door. — told + objeto + to + verbo."]], ex:["I asked her why she was crying.","Le pregunté por qué lloraba."]}
 ], qs:[
  {q:"'Do you like Indian food?' he asked me. → He asked me ____ I liked Indian food.", a:"if/whether — sin 'do', y 'liked' con retroceso."},
  {q:"Choose: She asked me where (I lived / did I live).", a:"I lived — orden afirmativo."},
  {q:"Correct the mistake: 'Don't be late,' she said. → She told me don't be late.", a:"She told me not to be late. — órdenes negativas: not to + verbo."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🗯️", t:"Reporting Verbs (suggest, admit, promise...)", es:"Verbos de comunicación indirecta", d:"Verbos como suggest, admit o promise y las estructuras que exigen.",
 boxes:[
  {e:"🤝", h:"Verb + to-infinitive", es:"Verb + to + infinitivo", i:[["promise, offer, refuse, agree: He promised to ring.","promise, offer, refuse, agree: Prometió llamar."],["threaten, decide: She decided to stay.","threaten, decide: Decidió quedarse."]], ex:["They agreed to meet at six.","Acordaron encontrarse a las seis."]},
  {e:"👤", h:"Verb + object + to", es:"Verb + objeto + to", i:[["tell, ask, warn, advise, remind, invite: She advised me to rest.","tell, ask, warn, advise, remind, invite: Me aconsejó descansar."],["order, encourage, persuade: He persuaded me to join.","order, encourage, persuade: Me convenció de unirme."]], ex:["He reminded me to post the letter.","Me recordó que enviara la carta."]},
  {e:"🔤", h:"Verb + -ing", es:"Verb + -ing", i:[["suggest, admit, deny, recommend: He suggested going to the pub.","suggest, admit, deny, recommend: Sugirió ir al pub."],["mention, regret: She regretted telling him.","mention, regret: Lamentó habérselo dicho."]], ex:["He admitted breaking the window.","Admitió haber roto la ventana."]},
  {e:"🛣️", h:"Verb + preposition + -ing", es:"Con preposición", i:[["apologise for: He apologised for being late.","apologise for: Se disculpó por llegar tarde."],["insist on, accuse of, blame for: She accused him of lying.","insist on, accuse of, blame for: Lo acusó de mentir."]], ex:["They insisted on paying.","Insistieron en pagar."]},
  {e:"📎", h:"Suggest: other patterns", es:"Suggest", i:[["suggest + (that) + subject + should / base verb: She suggested that we leave early.","suggest + (that) + sujeto + should / verbo base: Sugirió que nos fuéramos pronto."],["suggest + -ing: She suggested taking a taxi.","suggest + -ing: Sugirió tomar un taxi."]], ex:["I suggested that he should see a doctor.","Sugerí que fuera al médico."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ He suggested me to go.","✓ He suggested going / that I go. — 'suggest' no admite 'me to'."],["✗ She explained me the problem.","✓ She explained the problem to me. — explain + algo + to + persona."],["✗ He admitted to break the window.","✓ He admitted breaking the window. — admit + -ing."]], ex:["He explained the problem to us.","Nos explicó el problema."]}
 ], qs:[
  {q:"'I'll definitely pay you back,' she said. → She ____ (promise) ____ (pay) me back.", a:"promised to pay — promise + to + infinitivo."},
  {q:"Choose: He (denied to take / denied taking) the money.", a:"denied taking — deny + -ing."},
  {q:"Correct the mistake: She apologised me for being late.", a:"She apologised for being late. / She apologised to me for being late. — apologise (to) + for + -ing."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"🗣️", t:"Say, Tell, Speak & Talk", es:"Say, tell, speak y talk", d:"Diferencias, colocaciones y estructuras de cuatro verbos que se confunden mucho.",
 boxes:[
  {e:"💬", h:"Say", es:"Say: decir", i:[["say + words / that-clause: She said (that) she was late.","say + palabras / oración: Dijo que llegaba tarde."],["say + to + person: He said sorry to her.","say + to + persona: Le pidió perdón."],["say hello / goodbye / thank you / a prayer","decir hola / adiós / gracias / rezar una oración"]], ex:["What did he say?","¿Qué dijo?"]},
  {e:"🗨️", h:"Tell", es:"Tell: contar, decir a alguien", i:[["tell + person + that/to: She told me to wait.","tell + persona + that/to: Me dijo que esperara."],["tell the truth / a lie / a story / a joke","decir la verdad / una mentira / contar una historia / un chiste"],["tell the time / the difference / tell someone off","decir la hora / distinguir / regañar a alguien"]], ex:["Can you tell me the way to the station?","¿Puedes decirme el camino a la estación?"]},
  {e:"🌍", h:"Speak", es:"Speak: hablar (idiomas, formal)", i:[["speak a language: He speaks Welsh.","hablar un idioma: Habla galés."],["speak to / with someone (formal): Can I speak to the manager?","hablar con alguien (formal): ¿Puedo hablar con el gerente?"],["speak up / speak out / speak your mind","hablar más alto / pronunciarse / decir lo que piensas"]], ex:["Could you speak more slowly, please?","¿Podría hablar más despacio, por favor?"]},
  {e:"☕", h:"Talk", es:"Talk: conversar", i:[["talk to / with someone about something: We talked about football.","hablar con alguien de algo: Hablamos de fútbol."],["talk nonsense / sense / business","decir tonterías / hablar con sentido / hablar de negocios"],["a talk = a lecture or chat: She gave a talk on climate change.","una charla: Dio una charla sobre el cambio climático."]], ex:["We need to talk about your exam results.","Tenemos que hablar de tus resultados del examen."]},
  {e:"🇬🇧", h:"British usage", es:"Uso británico", i:[["have a word with someone: I'll have a word with him.","hablar un momento con alguien: Hablaré con él."],["have a chat / natter (informal): We had a good natter.","charlar / cotorrear (informal): Tuvimos una buena charla."],["Tell me about...! / You're telling me!","¡Cuéntame...! / ¡Me lo dices a mí!"]], ex:["Can I have a quick word?","¿Puedo hablar un momento contigo?"]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ She said me the truth.","✓ She told me the truth. — tell + persona; say no lleva persona directa."],["✗ He told that he was ill.","✓ He said (that) he was ill. / He told me (that) he was ill. — say sin persona; tell con persona."],["✗ I talk Spanish and French.","✓ I speak Spanish and French. — idiomas: speak; 'talk' se usa con about/to."]], ex:["She speaks three languages.","Habla tres idiomas."]}
 ], qs:[
  {q:"Fill the gap: He ____ me a funny joke at the pub. (said / told)", a:"told — tell a joke."},
  {q:"Choose: Can I (speak / say) to the manager, please?", a:"speak — formal, hablar con alguien."},
  {q:"Correct the mistake: She said me that she was leaving.", a:"She told me (that) she was leaving. / She said (that) she was leaving. — say no lleva 'me'."}
 ] },

{ cat:"Grammar: Tenses & Verbs", type:"Grammar", lvl:"B2", icon:"📰", t:"Passive Reporting Structures (It is said that…, He is thought to…)", es:"Pasiva impersonal (Se dice que…, Se cree que…)", d:"Cómo dar información general o de prensa sin decir quién lo afirma.",
 boxes:[
  {e:"🧱", h:"It is said that…", es:"Estructura con It", i:[["It + passive verb + that + clause: It is said that he is rich.","It + verbo pasivo + that + oración: Se dice que es rico."],["It was reported that the road was closed.","Se informó de que la carretera estaba cerrada."]], ex:["It is believed that the thief escaped by car.","Se cree que el ladrón escapó en auto."]},
  {e:"👤", h:"He is said to…", es:"Sujeto + infinitivo", i:[["Subject + passive verb + to + infinitive: He is said to be rich.","Sujeto + verbo pasivo + to + infinitivo: Se dice que es rico."],["They are thought to live in Kent.","Se cree que viven en Kent."]], ex:["The cathedral is known to be 800 years old.","Se sabe que la catedral tiene 800 años."]},
  {e:"⏮️", h:"Earlier events: to have + pp", es:"Hechos anteriores", i:[["to have + pp for the past: He is said to have left.","to have + participio para el pasado: Se dice que se fue."],["The minister is thought to have resigned.","Se cree que el ministro ha renunciado."]], ex:["She is believed to have won £1 million.","Se cree que ha ganado un millón de libras."]},
  {e:"📝", h:"Common verbs", es:"Verbos frecuentes", i:[["say, think, believe, know, expect, consider","decir, pensar, creer, saber, esperar, considerar"],["report, claim, allege, understand, rumour","informar, afirmar, alegar, entender, circular el rumor"]], ex:["The prime minister is expected to announce a new plan.","Se espera que el primer ministro anuncie un nuevo plan."]},
  {e:"⏱️", h:"Continuous infinitive", es:"Infinitivo continuo", i:[["to be + -ing for now: He is said to be living abroad.","to be + -ing para el presente: Se dice que vive en el extranjero."],["Used in news: The man is thought to be hiding in London.","Usado en noticias: Se cree que el hombre se esconde en Londres."]], ex:["They are believed to be working on a new album.","Se cree que están trabajando en un nuevo álbum."]},
  {e:"⚠️", h:"Common mistakes", es:"Errores típicos", i:[["✗ It is said him to be rich.","✓ He is said to be rich. / It is said that he is rich. — dos estructuras posibles."],["✗ He is said that he is rich.","✓ It is said that he is rich. — 'that' pide 'It' como sujeto."],["✗ He is believed to left.","✓ He is believed to have left. — hecho anterior: to have + participio."]], ex:["He is said to be the best chef in Britain.","Se dice que es el mejor cocinero de Gran Bretaña."]}
 ], qs:[
  {q:"Rewrite: People say that the shop is closing. → The shop ____ closing.", a:"is said to be — sujeto + pasiva + infinitivo continuo."},
  {q:"Choose: It (is thought / is thinking) that the fire started in the kitchen.", a:"is thought — pasiva: se piensa."},
  {q:"Correct the mistake: She is believed to won the lottery last year.", a:"She is believed to have won the lottery last year. — hecho pasado: to have + participio."}
 ] }
]);
